const { chromium } = require('@playwright/test');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
(async () => {
  const root = path.resolve(__dirname, '../..');
  const output = path.join(root, 'docs/assets/audit-lovable-2026-10-28');
  fs.mkdirSync(output, { recursive: true });
  const url = pathToFileURL(path.join(root, 'maquettes/menu-sections-2026-10-28/index.html')).href;
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const results = [];
  const assert = (value, label) => { if (!value) throw new Error(label); results.push(label); };
  for (const width of [390, 1440]) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto(url);
    await page.locator('img').evaluateAll(images => Promise.all(images.map(img => img.complete ? Promise.resolve() : new Promise(resolve => { img.onload = resolve; img.onerror = resolve; }))));
    const toggle = page.getByRole('button', { name: 'Ouvrir les sections' });
    const before = await toggle.boundingBox();
    assert(Math.abs(before.x + before.width - width) < 1, `closed handle at right edge ${width}`);
    assert(await page.locator('#section-drawer').evaluate(e => e.inert), `closed drawer inert ${width}`);
    await page.screenshot({ path: path.join(output, `menu-ferme-${width}.png`) });
    await toggle.click();
    await page.locator('#drawer-toggle[aria-expanded="true"]').waitFor();
    await page.locator('#section-drawer').evaluate(e => Promise.all(e.getAnimations().map(a => a.finished)));
    const after = await page.locator('#drawer-toggle').boundingBox();
    const panel = await page.locator('#section-drawer').boundingBox();
    assert(after.x < before.x, `handle travels left when opening ${width}`);
    assert(Math.abs(panel.x + panel.width - width) < 1, `drawer stays anchored at right ${width}`);
    assert(await page.locator('#section-links a').count() === 15, `fifteen named sections ${width}`);
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), `no horizontal overflow ${width}`);
    const anchorsValid = await page.locator('#section-links a').evaluateAll(links => links.every(a => document.getElementById(a.hash.slice(1))));
    assert(anchorsValid, `mock links target real mock anchors ${width}`);
    await page.screenshot({ path: path.join(output, `menu-ouvert-${width}.png`) });
    await page.keyboard.press('Shift+Tab');
    assert(await page.locator('#drawer-toggle').evaluate(e => e === document.activeElement), `focus wraps inside open controls ${width}`);
    await page.keyboard.press('Escape');
    assert(await page.locator('#drawer-toggle').getAttribute('aria-expanded') === 'false', `escape closes ${width}`);
    assert(await page.locator('#drawer-toggle').evaluate(e => e === document.activeElement), `focus returns to arrow ${width}`);
  }
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto(url);
  assert(await page.locator('#section-drawer').evaluate(e => getComputedStyle(e).transitionDuration === '0s'), 'reduced motion honored');
  await page.setViewportSize({ width: 1500, height: 1000 });
  await page.goto(pathToFileURL(path.join(root, 'maquettes/menu-sections-2026-10-28/apercu.html')).href);
  await page.frameLocator('iframe[title="Menu ouvert"]').locator('#drawer-toggle[aria-expanded="true"]').waitFor();
  await page.frameLocator('iframe[title="Menu ouvert"]').locator('#section-drawer').evaluate(e => Promise.all(e.getAnimations().map(a => a.finished)));
  await page.screenshot({ path: path.join(output, 'menu-ferme-ouvert.png'), fullPage: true });
  fs.writeFileSync(path.join(output, 'mock-verification.json'), JSON.stringify({ date: '2026-10-28', mode: 'Local file, isolated HTML mock only', passed: results.length, checks: results, applicationChanged: false, deployment: false }, null, 2) + '\n');
  await browser.close();
  console.log(JSON.stringify({ passed: results.length, captures: 5 }));
})().catch(error => { console.error(error); process.exitCode = 1; });
